// Decode the embedded Unicode maps and text runs produced by package:pdf.
// This keeps report-label assertions on the generated bytes, not source strings.
String pdfText(List<int> bytes) {
  final raw = latin1.decode(bytes);
  final streams = <String>[];
  for (final match in RegExp(
    r'<<(.*?)>>\s*stream\r?\n(.*?)\r?\nendstream',
    dotAll: true,
  ).allMatches(raw)) {
    final data = latin1.encode(match[2]!);
    streams.add(
      latin1.decode(
        match[1]!.contains('/FlateDecode') ? zlib.decode(data) : data,
      ),
    );
  }
  final maps = streams
      .where((s) => s.contains('beginbfchar'))
      .map(
        (s) => {
          for (final pair in RegExp(
            r'<([0-9A-F]{4})>\s*<([0-9A-F]{4})>',
          ).allMatches(s))
            pair[1]!: String.fromCharCode(int.parse(pair[2]!, radix: 16)),
        },
      );
  final content = streams.where((s) => s.contains('BT')).join(' ');
  return maps
      .map(
        (map) => RegExp(r'<([0-9A-Fa-f]+)>').allMatches(content).map((run) {
          final hex = run[1]!;
          return [
            for (var i = 0; i + 4 <= hex.length; i += 4)
              map[hex.substring(i, i + 4).toUpperCase()] ?? '',
          ].join();
        }).join(),
      )
      .join(' ')
      .replaceAll(RegExp(r'\s+'), '');
}

void main() {
  final entries = [
    WorkEntry(
      id: '1',
      date: DateTime(2026, 7, 9),
      siteName: 'Station, Road',
      startTime: '08:00',
      finishTime: '17:00',
      breakMinutes: 30,
      workLocation: 'Away',
      hourlyRateUsed: 20,
      dailyAllowance: 10,
      jobUplift: 25,
      totalHours: 8.5,
      wages: 170,
      totalPay: 205,
      notes: 'Completed "snagging"',
    ),
    WorkEntry(
      id: '2',
      entryType: 'Holiday',
      date: DateTime(2026, 7, 10),
      siteName: '',
      startTime: '',
      finishTime: '',
      breakMinutes: 0,
      workLocation: 'Home',
      hourlyRateUsed: 20,
      dailyAllowance: 0,
      jobUplift: 0,
      totalHours: 8,
      wages: 160,
      totalPay: 160,
      notes: '',
    ),
    WorkEntry(
      id: '3',
      entryType: 'UnpaidDayOff',
      date: DateTime(2026, 7, 11),
      siteName: '',
      startTime: '',
      finishTime: '',
      breakMinutes: 0,
      workLocation: 'Home',
      hourlyRateUsed: 0,
      dailyAllowance: 0,
      jobUplift: 5,
      totalHours: 0,
      wages: 0,
      totalPay: 5,
      notes: '',
    ),
  ];

  test('builds professional filenames for all export formats', () {
    expect(
      ExportFileNamer.buildFileName(
        fullName: 'Danny Buck',
        companyName: '',
        periodLabel: 'July 2026',
        fileNameLabel: 'July 2026',
        format: ExportFormat.excel,
      ),
      'Briska_Danny_Buck_July_2026.xlsx',
    );
    expect(
      ExportFileNamer.buildFileName(
        fullName: 'Danny Buck',
        companyName: '',
        periodLabel: 'July 2026',
        fileNameLabel: 'July 2026',
        format: ExportFormat.pdfTimesheet,
      ),
      'Briska_Danny_Buck_July_2026_Timesheet.pdf',
    );
    expect(
      ExportFileNamer.buildFileName(
        fullName: 'Danny Buck',
        companyName: '',
        periodLabel: 'July 2026',
        fileNameLabel: 'July 2026',
        format: ExportFormat.pdfSummary,
      ),
      'Briska_Danny_Buck_July_2026_Summary.pdf',
    );
    expect(
      ExportFileNamer.buildFileName(
        fullName: 'Danny Buck',
        companyName: 'CoolCanvas',
        periodLabel: 'July 2026',
        fileNameLabel: 'July 2026',
        format: ExportFormat.csv,
      ),
      'Briska_CoolCanvas_Danny_Buck_July_2026.csv',
    );
  });

  test(
    'builds CSV with headings, escaped values and spreadsheet-friendly BOM',
    () {
      final bytes = CsvExportService.buildCsv(entries);
      expect(bytes.take(3), [0xEF, 0xBB, 0xBF]);

      final csv = utf8.decode(bytes.skip(3).toList());
      expect(csv, startsWith('Date,Site/job,Day type'));
      expect(csv, contains('2026-07-09,"Station, Road",Work day'));
      expect(csv, contains('"Completed ""snagging"""'));
      expect(csv, contains('8.5,20.00,170.00,10.00,25.00,205.00'));
    },
  );

  test('calculates PDF summary totals without changing calculations', () {
    final totals = PdfExportService.calculateTotals(entries);

    expect(totals.workDays, 1);
    expect(totals.holidayDays, 1);
    expect(totals.unpaidDays, 1);
    expect(totals.hoursWorked, 8.5);
    expect(totals.averageHours, 8.5);
    expect(totals.holidayHours, 8);
    expect(totals.bankHolidayHours, 0);
    expect(totals.totalRecordedHours, 16.5);
    expect(totals.homePay, 160);
    expect(totals.awayPay, 170);
    expect(totals.allowances, 10);
    expect(totals.uplifts, 30);
    expect(totals.grossTotal, 370);
  });

  test('builds valid PDF timesheet and summary bytes', () async {
    final before = jsonEncode(entries.map((entry) => entry.toJson()).toList());
    final logo = File('assets/branding/briska-bp-in-app.png').readAsBytesSync();
    final regularFont = File(
      'assets/fonts/Poppins-Regular.ttf',
    ).readAsBytesSync();
    final boldFont = File(
      'assets/fonts/Poppins-SemiBold.ttf',
    ).readAsBytesSync();

    final timesheet = await PdfExportService.buildTimesheetPdf(
      entries,
      fullName: 'Danny Buck',
      companyName: 'CoolCanvas',
      periodLabel: 'July 2026',
      generatedAt: DateTime(2026, 7, 31),
      logoBytes: logo,
      regularFontBytes: regularFont,
      boldFontBytes: boldFont,
    );
    final summary = await PdfExportService.buildSummaryPdf(
      entries,
      fullName: 'Danny Buck',
      companyName: 'CoolCanvas',
      periodLabel: 'July 2026',
      generatedAt: DateTime(2026, 7, 31),
      logoBytes: logo,
      regularFontBytes: regularFont,
      boldFontBytes: boldFont,
    );

    expect(ascii.decode(timesheet.take(4).toList()), '%PDF');
    expect(ascii.decode(summary.take(4).toList()), '%PDF');
    expect(timesheet.length, greaterThan(1000));
    expect(summary.length, greaterThan(1000));
    expect(
      RegExp(r'/Type\s*/Page\b').allMatches(latin1.decode(summary)).length,
      1,
    );
    expect(jsonEncode(entries.map((entry) => entry.toJson()).toList()), before);
    if (Platform.environment['BRISKA_PDF_QA_DIR'] case final String path) {
      Directory(path).createSync(recursive: true);
      File('$path/timesheet.pdf').writeAsBytesSync(timesheet);
      File('$path/summary.pdf').writeAsBytesSync(summary);
    }
    for (final bytes in [timesheet, summary]) {
      final text = pdfText(bytes);
      for (final label in [
        'Hours Worked',
        'Average Hours Worked',
        'Holiday Hours',
        'Bank Holiday Hours',
        'Total Recorded Hours',
      ]) {
        expect(text, contains(label.replaceAll(' ', '')));
      }
    }
  });

  test('long PDF timesheet paginates and retains the hours summary', () async {
    final bytes = await PdfExportService.buildTimesheetPdf(
      [for (var day = 0; day < 45; day++) entries[day % entries.length]],
      fullName: 'Danny Buck',
      companyName: 'CoolCanvas',
      periodLabel: 'July 2026',
      generatedAt: DateTime(2026, 7, 31),
      logoBytes: File('assets/branding/briska-bp-in-app.png').readAsBytesSync(),
      regularFontBytes: File(
        'assets/fonts/Poppins-Regular.ttf',
      ).readAsBytesSync(),
      boldFontBytes: File(
        'assets/fonts/Poppins-SemiBold.ttf',
      ).readAsBytesSync(),
    );
    expect(
      RegExp(r'/Type\s*/Page\b').allMatches(latin1.decode(bytes)).length,
      greaterThan(1),
    );
    expect(pdfText(bytes), contains('TotalRecordedHours'));
    if (Platform.environment['BRISKA_PDF_QA_DIR'] case final String path) {
      Directory(path).createSync(recursive: true);
      File('$path/long-timesheet.pdf').writeAsBytesSync(bytes);
    }
  });

  test('builds Unicode currency PDF reports', () async {
    final logo = File('assets/branding/briska-bp-in-app.png').readAsBytesSync();
    final regularFont = File(
      'assets/fonts/Poppins-Regular.ttf',
    ).readAsBytesSync();
    final boldFont = File(
      'assets/fonts/Poppins-SemiBold.ttf',
    ).readAsBytesSync();

    for (final code in ['EUR', 'DKK', 'PLN', 'INR', 'JPY']) {
      final bytes = await PdfExportService.buildSummaryPdf(
        entries,
        fullName: 'Danny Buck',
        companyName: 'CoolCanvas',
        periodLabel: 'July 2026',
        generatedAt: DateTime(2026, 7, 31),
        logoBytes: logo,
        regularFontBytes: regularFont,
        boldFontBytes: boldFont,
        currency: CurrencyCatalog.byCode(code),
      );
      expect(ascii.decode(bytes.take(4).toList()), '%PDF', reason: code);
      expect(bytes.length, greaterThan(1000), reason: code);
    }
  });
  test('PDF exports do not change the application currency', () async {
    final originalCurrency = CurrencyFormatter.current;
    final gbp = CurrencyCatalog.byCode('GBP');
    final eur = CurrencyCatalog.byCode('EUR');

    final logo = File('assets/branding/briska-bp-in-app.png').readAsBytesSync();
    final regularFont = File(
      'assets/fonts/Poppins-Regular.ttf',
    ).readAsBytesSync();
    final boldFont = File(
      'assets/fonts/Poppins-SemiBold.ttf',
    ).readAsBytesSync();

    try {
      CurrencyFormatter.current = gbp;

      final timesheet = await PdfExportService.buildTimesheetPdf(
        entries,
        fullName: 'Test Employee',
        companyName: 'Test Company',
        periodLabel: 'July 2026',
        generatedAt: DateTime(2026, 7, 31),
        logoBytes: logo,
        regularFontBytes: regularFont,
        boldFontBytes: boldFont,
        currency: eur,
      );

      expect(CurrencyFormatter.current.code, 'GBP');

      final summary = await PdfExportService.buildSummaryPdf(
        entries,
        fullName: 'Test Employee',
        companyName: 'Test Company',
        periodLabel: 'July 2026',
        generatedAt: DateTime(2026, 7, 31),
        logoBytes: logo,
        regularFontBytes: regularFont,
        boldFontBytes: boldFont,
        currency: eur,
      );

      expect(CurrencyFormatter.current.code, 'GBP');
      for (final bytes in [timesheet, summary]) {
        final text = pdfText(bytes);
        expect(text, contains(eur.symbol));
        expect(text, isNot(contains(gbp.symbol)));
      }
    } finally {
      CurrencyFormatter.current = originalCurrency;
    }
  });
  test('PDF reports omit disabled employee and company fields', () async {
    final logo = File('assets/branding/briska-bp-in-app.png').readAsBytesSync();
    final regularFont = File(
      'assets/fonts/Poppins-Regular.ttf',
    ).readAsBytesSync();
    final boldFont = File(
      'assets/fonts/Poppins-SemiBold.ttf',
    ).readAsBytesSync();

    final timesheet = await PdfExportService.buildTimesheetPdf(
      entries,
      fullName: '',
      companyName: '',
      periodLabel: 'July 2026',
      generatedAt: DateTime(2026, 7, 31),
      logoBytes: logo,
      regularFontBytes: regularFont,
      boldFontBytes: boldFont,
    );

    final summary = await PdfExportService.buildSummaryPdf(
      entries,
      fullName: '',
      companyName: '',
      periodLabel: 'July 2026',
      generatedAt: DateTime(2026, 7, 31),
      logoBytes: logo,
      regularFontBytes: regularFont,
      boldFontBytes: boldFont,
    );

    for (final bytes in [timesheet, summary]) {
      final text = pdfText(bytes);

      expect(text, isNot(contains('Notprovided')));
      expect(text, isNot(contains('UserName')));
      expect(text, isNot(contains('Employer/company')));
      expect(text, contains('July2026'));
      expect(text, contains('BriskaPay'));
    }
  });
}
